/**
 * @file scalar_autograd.c
 * @brief ISO C23 Micrograd-style scalar reverse-mode automatic differentiation engine.
 * 
 * Part of RCRE Unified Engine.
 */

#include <math.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

/* Per-thread visited-epoch counter (C11 thread_local). Marking is done by
 * epoch comparison instead of clearing `visited_id` after every traversal,
 * and each thread owns its own counter, so concurrent scalar backward()
 * calls on DISJOINT graphs from different threads are safe. Traversing the
 * same graph from two threads simultaneously is still not supported (grad
 * accumulation is not atomic). Wraparound needs 2^32 traversals per thread.
 */
static thread_local uint32_t g_visited_epoch = 1;

static RCRE_ScalarVal* rcre_scalar_alloc_internal(RCRE_GraphCtx* ctx, bool is_param) {
    if (ctx == nullptr) return nullptr;
    RCRE_Arena* target_arena = (is_param ? ctx->persistent_arena : ctx->tape_arena);
    if (target_arena == nullptr) return nullptr;

    RCRE_ScalarVal* v = (RCRE_ScalarVal*)rcre_arena_alloc(target_arena, sizeof(RCRE_ScalarVal), alignof(RCRE_ScalarVal));
    if (!v) return nullptr;

    v->data = 0.0;
    v->grad = 0.0;
    v->backward = nullptr;
    v->prev[0] = nullptr;
    v->prev[1] = nullptr;
    v->op = RCRE_SCALAR_OP_CONST;
    v->label = nullptr;
    v->visited_id = 0;
    return v;
}

RCRE_ScalarVal* rcre_scalar_val_new(RCRE_GraphCtx* ctx, double data, const char* label) {
    RCRE_ScalarVal* v = rcre_scalar_alloc_internal(ctx, false);
    if (!v) return nullptr;
    v->data = data;
    v->label = label;
    v->op = RCRE_SCALAR_OP_CONST;
    return v;
}

RCRE_ScalarVal* rcre_scalar_val_param(RCRE_GraphCtx* ctx, double data, const char* label) {
    RCRE_ScalarVal* v = rcre_scalar_alloc_internal(ctx, true);
    if (!v) return nullptr;
    v->data = data;
    v->label = label;
    v->op = RCRE_SCALAR_OP_PARAM;
    return v;
}

RCRE_ScalarVal* rcre_scalar_val_const(RCRE_GraphCtx* ctx, double data) {
    return rcre_scalar_val_new(ctx, data, nullptr);
}

/* Backward callbacks */
static void scalar_backward_add(RCRE_ScalarVal* self) {
    if (self->prev[0]) self->prev[0]->grad += self->grad;
    if (self->prev[1]) self->prev[1]->grad += self->grad;
}

static void scalar_backward_sub(RCRE_ScalarVal* self) {
    if (self->prev[0]) self->prev[0]->grad += self->grad;
    if (self->prev[1]) self->prev[1]->grad -= self->grad;
}

static void scalar_backward_mul(RCRE_ScalarVal* self) {
    if (self->prev[0] && self->prev[1]) {
        self->prev[0]->grad += self->prev[1]->data * self->grad;
        self->prev[1]->grad += self->prev[0]->data * self->grad;
    }
}

static void scalar_backward_div(RCRE_ScalarVal* self) {
    if (self->prev[0] && self->prev[1]) {
        double d = self->prev[1]->data;
        self->prev[0]->grad += (1.0 / d) * self->grad;
        self->prev[1]->grad += (-self->prev[0]->data / (d * d)) * self->grad;
    }
}

static void scalar_backward_pow(RCRE_ScalarVal* self) {
    if (self->prev[0] && self->prev[1]) {
        double base = self->prev[0]->data;
        double exp_val = self->prev[1]->data;
        self->prev[0]->grad += (exp_val * pow(base, exp_val - 1.0)) * self->grad;
        if (base > 0.0) {
            self->prev[1]->grad += (pow(base, exp_val) * log(base)) * self->grad;
        }
    }
}

static void scalar_backward_relu(RCRE_ScalarVal* self) {
    if (self->prev[0]) {
        self->prev[0]->grad += (self->data > 0.0 ? 1.0 : 0.0) * self->grad;
    }
}

static void scalar_backward_tanh(RCRE_ScalarVal* self) {
    if (self->prev[0]) {
        double t = self->data;
        self->prev[0]->grad += (1.0 - t * t) * self->grad;
    }
}

static void scalar_backward_sigmoid(RCRE_ScalarVal* self) {
    if (self->prev[0]) {
        double s = self->data;
        self->prev[0]->grad += s * (1.0 - s) * self->grad;
    }
}

static void scalar_backward_exp(RCRE_ScalarVal* self) {
    if (self->prev[0]) {
        self->prev[0]->grad += self->data * self->grad;
    }
}

static void scalar_backward_log(RCRE_ScalarVal* self) {
    if (self->prev[0]) {
        self->prev[0]->grad += (1.0 / (self->prev[0]->data + 1e-15)) * self->grad;
    }
}

static void scalar_backward_neg(RCRE_ScalarVal* self) {
    if (self->prev[0]) {
        self->prev[0]->grad -= self->grad;
    }
}

RCRE_ScalarVal* rcre_scalar_add(RCRE_GraphCtx* ctx, RCRE_ScalarVal* a, RCRE_ScalarVal* b) {
    RCRE_ScalarVal* out = rcre_scalar_alloc_internal(ctx, false);
    if (!out) return nullptr;
    out->data = a->data + b->data;
    out->prev[0] = a;
    out->prev[1] = b;
    out->op = RCRE_SCALAR_OP_ADD;
    out->backward = scalar_backward_add;
    return out;
}

RCRE_ScalarVal* rcre_scalar_sub(RCRE_GraphCtx* ctx, RCRE_ScalarVal* a, RCRE_ScalarVal* b) {
    RCRE_ScalarVal* out = rcre_scalar_alloc_internal(ctx, false);
    if (!out) return nullptr;
    out->data = a->data - b->data;
    out->prev[0] = a;
    out->prev[1] = b;
    out->op = RCRE_SCALAR_OP_SUB;
    out->backward = scalar_backward_sub;
    return out;
}

RCRE_ScalarVal* rcre_scalar_mul(RCRE_GraphCtx* ctx, RCRE_ScalarVal* a, RCRE_ScalarVal* b) {
    RCRE_ScalarVal* out = rcre_scalar_alloc_internal(ctx, false);
    if (!out) return nullptr;
    out->data = a->data * b->data;
    out->prev[0] = a;
    out->prev[1] = b;
    out->op = RCRE_SCALAR_OP_MUL;
    out->backward = scalar_backward_mul;
    return out;
}

RCRE_ScalarVal* rcre_scalar_div(RCRE_GraphCtx* ctx, RCRE_ScalarVal* a, RCRE_ScalarVal* b) {
    RCRE_ScalarVal* out = rcre_scalar_alloc_internal(ctx, false);
    if (!out) return nullptr;
    out->data = a->data / (b->data + 1e-15);
    out->prev[0] = a;
    out->prev[1] = b;
    out->op = RCRE_SCALAR_OP_DIV;
    out->backward = scalar_backward_div;
    return out;
}

RCRE_ScalarVal* rcre_scalar_pow(RCRE_GraphCtx* ctx, RCRE_ScalarVal* base, RCRE_ScalarVal* exponent) {
    RCRE_ScalarVal* out = rcre_scalar_alloc_internal(ctx, false);
    if (!out) return nullptr;
    out->data = pow(base->data, exponent->data);
    out->prev[0] = base;
    out->prev[1] = exponent;
    out->op = RCRE_SCALAR_OP_POW;
    out->backward = scalar_backward_pow;
    return out;
}

RCRE_ScalarVal* rcre_scalar_relu(RCRE_GraphCtx* ctx, RCRE_ScalarVal* a) {
    RCRE_ScalarVal* out = rcre_scalar_alloc_internal(ctx, false);
    if (!out) return nullptr;
    out->data = a->data > 0.0 ? a->data : 0.0;
    out->prev[0] = a;
    out->op = RCRE_SCALAR_OP_RELU;
    out->backward = scalar_backward_relu;
    return out;
}

RCRE_ScalarVal* rcre_scalar_tanh(RCRE_GraphCtx* ctx, RCRE_ScalarVal* a) {
    RCRE_ScalarVal* out = rcre_scalar_alloc_internal(ctx, false);
    if (!out) return nullptr;
    out->data = tanh(a->data);
    out->prev[0] = a;
    out->op = RCRE_SCALAR_OP_TANH;
    out->backward = scalar_backward_tanh;
    return out;
}

RCRE_ScalarVal* rcre_scalar_sigmoid(RCRE_GraphCtx* ctx, RCRE_ScalarVal* a) {
    RCRE_ScalarVal* out = rcre_scalar_alloc_internal(ctx, false);
    if (!out) return nullptr;
    out->data = 1.0 / (1.0 + exp(-a->data));
    out->prev[0] = a;
    out->op = RCRE_SCALAR_OP_SIGMOID;
    out->backward = scalar_backward_sigmoid;
    return out;
}

RCRE_ScalarVal* rcre_scalar_exp(RCRE_GraphCtx* ctx, RCRE_ScalarVal* a) {
    RCRE_ScalarVal* out = rcre_scalar_alloc_internal(ctx, false);
    if (!out) return nullptr;
    out->data = exp(a->data);
    out->prev[0] = a;
    out->op = RCRE_SCALAR_OP_EXP;
    out->backward = scalar_backward_exp;
    return out;
}

RCRE_ScalarVal* rcre_scalar_log(RCRE_GraphCtx* ctx, RCRE_ScalarVal* a) {
    RCRE_ScalarVal* out = rcre_scalar_alloc_internal(ctx, false);
    if (!out) return nullptr;
    out->data = log(a->data > 1e-15 ? a->data : 1e-15);
    out->prev[0] = a;
    out->op = RCRE_SCALAR_OP_LOG;
    out->backward = scalar_backward_log;
    return out;
}

RCRE_ScalarVal* rcre_scalar_neg(RCRE_GraphCtx* ctx, RCRE_ScalarVal* a) {
    RCRE_ScalarVal* out = rcre_scalar_alloc_internal(ctx, false);
    if (!out) return nullptr;
    out->data = -a->data;
    out->prev[0] = a;
    out->op = RCRE_SCALAR_OP_NEG;
    out->backward = scalar_backward_neg;
    return out;
}

/* Topological sort vector */
typedef struct {
    RCRE_ScalarVal** items;
    size_t count;
    size_t capacity;
} RCRE_ValVec;

static void scalar_vec_push(RCRE_ValVec* vec, RCRE_ScalarVal* v) {
    if (vec->count >= vec->capacity) {
        size_t new_cap = (vec->capacity == 0) ? 128 : vec->capacity * 2;
        /* Realloc via temporary pointer: on failure the old buffer stays
         * intact and is returned; callers treat a missing node as OOM. */
        RCRE_ScalarVal** new_items = (RCRE_ScalarVal**)realloc(vec->items, new_cap * sizeof(RCRE_ScalarVal*));
        if (!new_items) return;
        vec->items = new_items;
        vec->capacity = new_cap;
    }
    vec->items[vec->count++] = v;
}

/* Iterative postorder topological sort (explicit stack).
 *
 * The previous recursive DFS consumed ~100 bytes of C stack per node, so a
 * chain of ~50k nodes (plausible for unrolled RNNs or JIT-generated DAGs)
 * overflowed an 8 MB stack. The explicit frame stack lives on the heap and
 * supports arbitrarily deep chains. Cycles are not detected: as before, a
 * back-edge is simply treated as an already-visited node.
 */
typedef struct {
    RCRE_ScalarVal* node;
    uint8_t         stage; /* 0 = entering, 1 = children done, emit node */
} topo_frame_t;

typedef struct {
    topo_frame_t* frames;
    size_t        count;
    size_t        capacity;
} RCRE_FrameStack;

static bool frame_push(RCRE_FrameStack* fs, RCRE_ScalarVal* node, uint8_t stage) {
    if (fs->count >= fs->capacity) {
        size_t new_cap = (fs->capacity == 0) ? 256 : fs->capacity * 2;
        topo_frame_t* nf = (topo_frame_t*)realloc(fs->frames, new_cap * sizeof(topo_frame_t));
        if (!nf) return false; /* OOM: old stack intact; traversal stops early */
        fs->frames = nf;
        fs->capacity = new_cap;
    }
    fs->frames[fs->count].node = node;
    fs->frames[fs->count].stage = stage;
    fs->count++;
    return true;
}

static bool build_topo(RCRE_ScalarVal* root, uint32_t epoch, RCRE_ValVec* topo) {
    if (root == nullptr) return true;

    RCRE_FrameStack fs = { .frames = nullptr, .count = 0, .capacity = 0 };
    if (!frame_push(&fs, root, 0)) return false;

    while (fs.count > 0) {
        topo_frame_t* top = &fs.frames[fs.count - 1];
        RCRE_ScalarVal* v = top->node;

        if (top->stage == 0) {
            if (v->visited_id == epoch) {
                fs.count--; /* fully processed already (DAG sharing) */
                continue;
            }
            v->visited_id = epoch;
            top->stage = 1;
            /* Push prev[1] first so prev[0]'s subtree is emitted first,
             * matching the old recursive child order exactly. A failed
             * push aborts the traversal (caller bails: partial topo would
             * produce silently wrong gradients). */
            if (v->prev[1] != nullptr && v->prev[1]->visited_id != epoch) {
                if (!frame_push(&fs, v->prev[1], 0)) { free(fs.frames); return false; }
            }
            if (v->prev[0] != nullptr && v->prev[0]->visited_id != epoch) {
                if (!frame_push(&fs, v->prev[0], 0)) { free(fs.frames); return false; }
            }
        } else {
            fs.count--;
            scalar_vec_push(topo, v);
        }
    }

    free(fs.frames);
    return true;
}

void rcre_scalar_backward(RCRE_ScalarVal* root) {
    if (root == nullptr) return;

    uint32_t epoch = ++g_visited_epoch;
    RCRE_ValVec topo = { .items = nullptr, .count = 0, .capacity = 0 };
    if (!build_topo(root, epoch, &topo)) {
        free(topo.items); /* OOM: no gradient update rather than a wrong one */
        return;
    }

    root->grad = 1.0;

    for (size_t i = topo.count; i > 0; --i) {
        RCRE_ScalarVal* curr = topo.items[i - 1];
        if (curr->backward != nullptr) {
            curr->backward(curr);
        }
    }

    if (topo.items != nullptr) {
        free(topo.items);
    }
}

void rcre_scalar_zero_grad(RCRE_ScalarVal* root) {
    if (root == nullptr) return;
    uint32_t epoch = ++g_visited_epoch;
    RCRE_ValVec topo = { .items = nullptr, .count = 0, .capacity = 0 };
    if (!build_topo(root, epoch, &topo)) {
        free(topo.items);
        return;
    }
    for (size_t i = 0; i < topo.count; ++i) {
        topo.items[i]->grad = 0.0;
    }
    if (topo.items != nullptr) {
        free(topo.items);
    }
}

bool rcre_scalar_export_dot(RCRE_ScalarVal* root, const char* filename) {
    if (root == nullptr || filename == nullptr) return false;

    FILE* f = fopen(filename, "w");
    if (!f) return false;

    fprintf(f, "digraph AutogradGraph {\n");
    fprintf(f, "  rankdir=LR;\n");
    fprintf(f, "  node [shape=record, style=filled, fillcolor=\"#F0F4F8\", fontname=\"Helvetica\"];\n");

    uint32_t epoch = ++g_visited_epoch;
    RCRE_ValVec topo = { .items = nullptr, .count = 0, .capacity = 0 };
    if (!build_topo(root, epoch, &topo)) {
        fclose(f);
        remove(filename); /* leave no partial artifact behind */
        return false;
    }

    for (size_t i = 0; i < topo.count; ++i) {
        RCRE_ScalarVal* n = topo.items[i];
        const char* lbl = n->label ? n->label : "";
        fprintf(f, "  node_%p [label=\"{%s|data: %.4f|grad: %.4f}\"];\n", (void*)n, lbl, n->data, n->grad);
        if (n->prev[0] != nullptr) {
            fprintf(f, "  node_%p -> node_%p;\n", (void*)n->prev[0], (void*)n);
        }
        if (n->prev[1] != nullptr) {
            fprintf(f, "  node_%p -> node_%p;\n", (void*)n->prev[1], (void*)n);
        }
    }

    fprintf(f, "}\n");
    fclose(f);
    if (topo.items != nullptr) free(topo.items);
    return true;
}

/* --- Source: tensor_autograd.c --- */
/**
 * @file tensor_autograd.c
 * @brief Dynamic Tensor Tape and Automatic Differentiation Engine for RCRE.
 *
 * Part of RCRE Unified Engine.
 *
 * Unified tensor model (v0.2.2): this file operates exclusively on
 * RCRE_Tensor (rcre.h). Training tensors are arena-owned RCRE_Tensor* with a
 * `grad` backprop buffer, produced by rcre_tensor_alloc*. All F32 element
 * access goes through rcre_tensor_f32_data(); operators validate dtype and
 * shape and return NULL (no tape node recorded) on any violation.
 */

#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <math.h>

#if defined(__APPLE__) && defined(RCRE_USE_BLAS)
#include <Accelerate/Accelerate.h>
#endif

/* ========================================================================= */
/* Internal General GEMM with Transpose Support                              */
/* ========================================================================= */

static void rcre_ag_gemm(bool transA, bool transB, size_t M, size_t N, size_t K,
                         float alpha, const float* A, size_t lda,
                         const float* B, size_t ldb,
                         float beta, float* C, size_t ldc) {
#if defined(__APPLE__) && defined(RCRE_USE_BLAS)
    cblas_sgemm(CblasRowMajor,
                transA ? CblasTrans : CblasNoTrans,
                transB ? CblasTrans : CblasNoTrans,
                (int)M, (int)N, (int)K,
                alpha, A, (int)lda,
                B, (int)ldb,
                beta, C, (int)ldc);
#else
    if (!transA && !transB) {
        rcre_hal.gemm_f32(M, N, K, alpha, A, lda, B, ldb, beta, C, ldc);
        return;
    }

    #define BLOCK_M 64
    #define BLOCK_N 64
    #define BLOCK_K 64

    for (size_t i = 0; i < M; ++i) {
        for (size_t j = 0; j < N; ++j) {
            if (beta == 0.0f) {
                C[i * ldc + j] = 0.0f;
            } else {
                C[i * ldc + j] *= beta;
            }
        }
    }

    for (size_t ii = 0; ii < M; ii += BLOCK_M) {
        size_t m_end = (ii + BLOCK_M < M) ? ii + BLOCK_M : M;
        for (size_t kk = 0; kk < K; kk += BLOCK_K) {
            size_t k_end = (kk + BLOCK_K < K) ? kk + BLOCK_K : K;
            for (size_t jj = 0; jj < N; jj += BLOCK_N) {
                size_t j_end = (jj + BLOCK_N < N) ? jj + BLOCK_N : N;

                for (size_t i = ii; i < m_end; ++i) {
                    for (size_t k = kk; k < k_end; ++k) {
                        float a_val = alpha * (transA ? A[k * lda + i] : A[i * lda + k]);
                        for (size_t j = jj; j < j_end; ++j) {
                            float b_val = transB ? B[j * ldb + k] : B[k * ldb + j];
                            C[i * ldc + j] += a_val * b_val;
                        }
                    }
                }
            }
        }
    }
#endif
}

/* ========================================================================= */
/* Training Tensor Allocation & Initialization (arena-owned RCRE_Tensor)     */
/* ========================================================================= */

static void compute_strides(const size_t* shape, uint8_t ndim, ptrdiff_t* strides) {
    if (ndim == 0) return;
    strides[ndim - 1] = 1;
    for (uint8_t i = ndim - 1; i > 0; --i) {
        strides[i - 1] = strides[i] * (ptrdiff_t)shape[i];
    }
}

static bool is_f32(const RCRE_Tensor* t) {
    return t != nullptr && t->data != nullptr && t->dtype == RCRE_DTYPE_F32 && t->ndim != 0;
}

RCRE_Tensor* rcre_tensor_alloc(RCRE_Arena* arena, const size_t* shape, uint8_t ndim) {
    if (arena == nullptr || ndim == 0 || ndim > 4 || shape == nullptr) return nullptr;

    RCRE_Tensor* t = (RCRE_Tensor*)rcre_arena_alloc(arena, sizeof(RCRE_Tensor), alignof(RCRE_Tensor));
    if (!t) return nullptr;

    /* Zero-initialize: fields beyond `ndim` must never read back
     * uninitialized memory (e.g. `y->shape[1]` on a 1-D tensor). */
    memset(t, 0, sizeof(RCRE_Tensor));

    t->ndim = ndim;
    t->dtype = RCRE_DTYPE_F32;
    t->layout = RCRE_LAYOUT_TABULAR;
    for (size_t i = 0; i < ndim; ++i) {
        t->shape[i] = shape[i];
    }
    t->numel = rcre_tensor_numel(t);
    compute_strides(t->shape, t->ndim, t->strides);
    t->is_view = false;
    t->label = nullptr;

    size_t byte_size = t->numel * sizeof(float);
    t->data = rcre_arena_alloc(arena, byte_size, 64);
    t->grad = (float*)rcre_arena_alloc(arena, byte_size, 64);
    if (!t->data || !t->grad) {
        return nullptr; /* arena space already consumed; rewind via temp checkpoint */
    }

    memset(t->data, 0, byte_size);
    memset(t->grad, 0, byte_size);
    return t;
}

RCRE_Tensor* rcre_tensor_alloc_1d(RCRE_Arena* arena, size_t d0) {
    size_t shape[1] = { d0 };
    return rcre_tensor_alloc(arena, shape, 1);
}

RCRE_Tensor* rcre_tensor_alloc_2d(RCRE_Arena* arena, size_t rows, size_t cols) {
    size_t shape[2] = { rows, cols };
    return rcre_tensor_alloc(arena, shape, 2);
}

RCRE_Tensor* rcre_tensor_alloc_4d(RCRE_Arena* arena, size_t n, size_t c, size_t h, size_t w) {
    size_t shape[4] = { n, c, h, w };
    return rcre_tensor_alloc(arena, shape, 4);
}

void rcre_tensor_fill(RCRE_Tensor* t, float val) {
    if (!is_f32(t)) return;
    for (size_t i = 0; i < t->numel; ++i) {
        rcre_tensor_f32_data(t)[i] = val;
    }
}

void rcre_tensor_zeros(RCRE_Tensor* t) {
    rcre_tensor_fill(t, 0.0f);
}

void rcre_tensor_ones(RCRE_Tensor* t) {
    rcre_tensor_fill(t, 1.0f);
}

void rcre_tensor_zero_grad(RCRE_Tensor* t) {
    if (t && t->grad) {
        memset(t->grad, 0, t->numel * sizeof(float));
    }
}

void rcre_tensor_init_xavier(RCRE_Tensor* t, size_t fan_in, size_t fan_out, uint64_t* rng) {
    if (!is_f32(t) || !rng || (fan_in + fan_out) == 0) return;
    float limit = sqrtf(6.0f / (float)(fan_in + fan_out));
    for (size_t i = 0; i < t->numel; ++i) {
        rcre_tensor_f32_data(t)[i] = rcre_rng_uniform_f32(rng, -limit, limit);
    }
}

void rcre_tensor_init_he(RCRE_Tensor* t, size_t fan_in, uint64_t* rng) {
    if (!is_f32(t) || !rng || fan_in == 0) return;
    float std = sqrtf(2.0f / (float)fan_in);
    for (size_t i = 0; i < t->numel; ++i) {
        rcre_tensor_f32_data(t)[i] = rcre_rng_gaussian_f32(rng, 0.0f, std);
    }
}

RCRE_Tensor* rcre_tensor_view(RCRE_Arena* arena, const RCRE_Tensor* src) {
    if (!src || arena == nullptr) return nullptr;
    RCRE_Tensor* v = (RCRE_Tensor*)rcre_arena_alloc(arena, sizeof(RCRE_Tensor), alignof(RCRE_Tensor));
    if (!v) return nullptr;
    *v = *src;
    v->grad = nullptr; /* parent grad is indexed in parent coordinates */
    v->is_view = true;
    return v;
}

RCRE_Tensor* rcre_tensor_reshape_view(RCRE_Arena* arena, const RCRE_Tensor* src, const size_t* new_shape, uint8_t new_ndim) {
    if (!src || new_ndim == 0 || new_ndim > 4 || !rcre_tensor_is_contiguous(src)) return nullptr;
    size_t new_numel = 1;
    for (size_t i = 0; i < new_ndim; ++i) {
        new_numel *= new_shape[i];
    }
    if (new_numel != rcre_tensor_numel(src)) return nullptr;

    RCRE_Tensor* v = rcre_tensor_view(arena, src);
    if (!v) return nullptr;
    v->ndim = new_ndim;
    for (size_t i = 0; i < new_ndim; ++i) {
        v->shape[i] = new_shape[i];
    }
    compute_strides(v->shape, v->ndim, v->strides);
    return v;
}

void rcre_tensor_print(const RCRE_Tensor* t, const char* name) {
    if (!t) return;
    printf("Tensor '%s' [ndim=%u, numel=%zu]:\n", name ? name : "unnamed", (unsigned)t->ndim, t->numel);
    if (t->ndim == 1) {
        printf("  [");
        for (size_t i = 0; i < t->numel && i < 10; ++i) {
            printf("%.4f%s", rcre_tensor_f32_data(t)[i], (i + 1 < t->numel) ? ", " : "");
        }
        if (t->numel > 10) printf("...");
        printf("]\n");
    } else if (t->ndim == 2) {
        for (size_t r = 0; r < t->shape[0] && r < 5; ++r) {
            printf("  [");
            for (size_t c = 0; c < t->shape[1] && c < 8; ++c) {
                printf("%.4f%s", rcre_tensor_f32_data(t)[r * (size_t)t->strides[0] + c], (c + 1 < t->shape[1]) ? ", " : "");
            }
            if (t->shape[1] > 8) printf("...");
            printf("]\n");
        }
        if (t->shape[0] > 5) printf("  ...\n");
    }
}

RCRE_Tensor* rcre_tensor_matmul(RCRE_Arena* arena, const RCRE_Tensor* a, const RCRE_Tensor* b) {
    if (!is_f32(a) || !is_f32(b) || a->ndim != 2 || b->ndim != 2 || a->shape[1] != b->shape[0]) return nullptr;
    size_t M = a->shape[0];
    size_t K = a->shape[1];
    size_t N = b->shape[1];

    RCRE_Tensor* c = rcre_tensor_alloc_2d(arena, M, N);
    if (!c) return nullptr;
    rcre_ag_gemm(false, false, M, N, K, 1.0f,
                 rcre_tensor_f32_data(a), (size_t)a->strides[0],
                 rcre_tensor_f32_data(b), (size_t)b->strides[0],
                 0.0f, rcre_tensor_f32_data(c), (size_t)c->strides[0]);
    return c;
}

void rcre_tensor_add_inplace(RCRE_Tensor* a, const RCRE_Tensor* b) {
    if (!is_f32(a) || !is_f32(b) || a->numel != b->numel) return;
    float* ad = rcre_tensor_f32_data(a);
    const float* bd = rcre_tensor_f32_data(b);
    for (size_t i = 0; i < a->numel; ++i) {
        ad[i] += bd[i];
    }
}

/* ========================================================================= */
/* Dynamic Tensor Tape Autograd Engine                                       */
/* ========================================================================= */

RCRE_TensorTape* rcre_tensor_tape_create(RCRE_Arena* arena, size_t initial_cap) {
    if (arena == nullptr) return nullptr;
    if (initial_cap < 8) initial_cap = 8;

    RCRE_TensorTape* tape = (RCRE_TensorTape*)rcre_arena_alloc(arena, sizeof(RCRE_TensorTape), alignof(RCRE_TensorTape));
    /* The node array is deliberately heap-owned (malloc/realloc), NOT arena
     * owned: callers may rewind the tape arena with rcre_arena_temp_end()
     * between batches, which would invalidate (and later clobber) any node
     * storage placed inside it. The tape struct itself lives in the arena.
     * NOTE: create the tape BEFORE taking your first temp checkpoint. */
    tape->nodes = (RCRE_TensorNode*)malloc(initial_cap * sizeof(RCRE_TensorNode));
    if (!tape || !tape->nodes) {
        if (tape->nodes) free(tape->nodes);
        return nullptr;
    }
    tape->count = 0;
    tape->capacity = initial_cap;
    tape->arena = arena;
    return tape;
}

void rcre_tensor_tape_destroy(RCRE_TensorTape* tape) {
    if (tape != nullptr && tape->nodes != nullptr) {
        free(tape->nodes);
        tape->nodes = nullptr;
        tape->capacity = 0;
        tape->count = 0;
    }
}

void rcre_tensor_tape_reset(RCRE_TensorTape* tape) {
    if (tape != nullptr) {
        tape->count = 0;
    }
}

static RCRE_TensorNode* tape_push_node(RCRE_TensorTape* tape) {
    if (tape->count >= tape->capacity) {
        size_t new_cap = tape->capacity * 2;
        /* Realloc via temporary pointer: on failure the old array is intact. */
        RCRE_TensorNode* new_nodes = (RCRE_TensorNode*)realloc(tape->nodes, new_cap * sizeof(RCRE_TensorNode));
        if (!new_nodes) return nullptr; /* OOM: node array unchanged, caller must handle NULL */
        tape->nodes = new_nodes;
        tape->capacity = new_cap;
    }
    return &tape->nodes[tape->count++];
}

static void backward_matmul(RCRE_TensorNode* node) {
    RCRE_Tensor* out = node->out;
    RCRE_Tensor* a = node->inputs[0];
    RCRE_Tensor* b = node->inputs[1];

    size_t M = a->shape[0];
    size_t K = a->shape[1];
    size_t N = b->shape[1];

    /* dA += dC * B^T */
    if (a->grad != nullptr) {
        rcre_ag_gemm(false, true, M, K, N, 1.0f, out->grad, N,
                     rcre_tensor_f32_data(b), N, 1.0f, a->grad, K);
    }

    /* dB += A^T * dC */
    if (b->grad != nullptr) {
        rcre_ag_gemm(true, false, K, N, M, 1.0f, rcre_tensor_f32_data(a), K,
                     out->grad, N, 1.0f, b->grad, N);
    }
}

static void backward_add(RCRE_TensorNode* node) {
    RCRE_Tensor* out = node->out;
    RCRE_Tensor* a = node->inputs[0];
    RCRE_Tensor* b = node->inputs[1];

    for (size_t i = 0; i < out->numel; ++i) {
        if (a->grad != nullptr) a->grad[i] += out->grad[i];
        if (b->grad != nullptr) b->grad[i] += out->grad[i];
    }
}

static void backward_add_bias(RCRE_TensorNode* node) {
    RCRE_Tensor* out = node->out;
    RCRE_Tensor* x = node->inputs[0];
    RCRE_Tensor* bias = node->inputs[1];

    size_t rows = out->shape[0];
    size_t cols = out->shape[1];

    for (size_t r = 0; r < rows; ++r) {
        const float* out_grad_row = out->grad + r * cols;
        float* x_grad_row = (x->grad != nullptr) ? (x->grad + r * cols) : nullptr;
        for (size_t c = 0; c < cols; ++c) {
            if (x_grad_row != nullptr) x_grad_row[c] += out_grad_row[c];
            if (bias->grad != nullptr) bias->grad[c] += out_grad_row[c];
        }
    }
}

static void backward_relu(RCRE_TensorNode* node) {
    RCRE_Tensor* out = node->out;
    RCRE_Tensor* x = node->inputs[0];

    if (x->grad == nullptr) return;
    const float* xd = rcre_tensor_f32_data(x);
    const float* og = out->grad;
    float* xg = x->grad;
    for (size_t i = 0; i < out->numel; ++i) {
        if (xd[i] > 0.0f) {
            xg[i] += og[i];
        }
    }
}

static void backward_sigmoid(RCRE_TensorNode* node) {
    RCRE_Tensor* out = node->out;
    RCRE_Tensor* x = node->inputs[0];

    if (x->grad == nullptr) return;
    const float* od = rcre_tensor_f32_data(out);
    const float* og = out->grad;
    float* xg = x->grad;
    for (size_t i = 0; i < out->numel; ++i) {
        float s = od[i];
        xg[i] += s * (1.0f - s) * og[i];
    }
}

void rcre_tensor_tape_backward(RCRE_TensorTape* tape) {
    if (!tape || tape->count == 0) return;
    for (size_t i = tape->count; i > 0; --i) {
        RCRE_TensorNode* node = &tape->nodes[i - 1];
        if (node->backward != nullptr) {
            node->backward(node);
        }
    }
}

RCRE_Tensor* rcre_autograd_matmul(RCRE_TensorTape* tape, RCRE_Tensor* a, RCRE_Tensor* b) {
    RCRE_Tensor* out = rcre_tensor_matmul(tape->arena, a, b);
    if (!out) return nullptr;

    RCRE_TensorNode* node = tape_push_node(tape);
    if (!node) return out; /* OOM: forward result valid, but graph is incomplete */
    node->out = out;
    node->inputs[0] = a;
    node->inputs[1] = b;
    node->num_inputs = 2;
    node->backward = backward_matmul;
    return out;
}

RCRE_Tensor* rcre_autograd_add(RCRE_TensorTape* tape, RCRE_Tensor* a, RCRE_Tensor* b) {
    if (!is_f32(a) || !is_f32(b) || a->numel != b->numel) return nullptr;
    RCRE_Tensor* out = rcre_tensor_alloc(tape->arena, a->shape, a->ndim);
    if (!out) return nullptr;
    const float* ad = rcre_tensor_f32_data(a);
    const float* bd = rcre_tensor_f32_data(b);
    float* od = rcre_tensor_f32_data(out);
    for (size_t i = 0; i < out->numel; ++i) {
        od[i] = ad[i] + bd[i];
    }

    RCRE_TensorNode* node = tape_push_node(tape);
    if (!node) return out;
    node->out = out;
    node->inputs[0] = a;
    node->inputs[1] = b;
    node->num_inputs = 2;
    node->backward = backward_add;
    return out;
}

RCRE_Tensor* rcre_autograd_add_bias(RCRE_TensorTape* tape, RCRE_Tensor* x, RCRE_Tensor* bias) {
    if (!is_f32(x) || !is_f32(bias) || x->ndim != 2 || bias->ndim != 1 || bias->shape[0] != x->shape[1]) return nullptr;
    size_t rows = x->shape[0];
    size_t cols = x->shape[1];

    RCRE_Tensor* out = rcre_tensor_alloc_2d(tape->arena, rows, cols);
    if (!out) return nullptr;
    const float* xd = rcre_tensor_f32_data(x);
    const float* bd = rcre_tensor_f32_data(bias);
    float* od = rcre_tensor_f32_data(out);
    for (size_t r = 0; r < rows; ++r) {
        const float* x_row = xd + r * cols;
        float* out_row = od + r * cols;
        for (size_t c = 0; c < cols; ++c) {
            out_row[c] = x_row[c] + bd[c];
        }
    }

    RCRE_TensorNode* node = tape_push_node(tape);
    if (!node) return out;
    node->out = out;
    node->inputs[0] = x;
    node->inputs[1] = bias;
    node->num_inputs = 2;
    node->backward = backward_add_bias;
    return out;
}

RCRE_Tensor* rcre_autograd_relu(RCRE_TensorTape* tape, RCRE_Tensor* x) {
    if (!is_f32(x)) return nullptr;
    RCRE_Tensor* out = rcre_tensor_alloc(tape->arena, x->shape, x->ndim);
    if (!out) return nullptr;
    const float* xd = rcre_tensor_f32_data(x);
    float* od = rcre_tensor_f32_data(out);
    for (size_t i = 0; i < out->numel; ++i) {
        od[i] = (xd[i] > 0.0f) ? xd[i] : 0.0f;
    }

    RCRE_TensorNode* node = tape_push_node(tape);
    if (!node) return out;
    node->out = out;
    node->inputs[0] = x;
    node->num_inputs = 1;
    node->backward = backward_relu;
    return out;
}

RCRE_Tensor* rcre_autograd_sigmoid(RCRE_TensorTape* tape, RCRE_Tensor* x) {
    if (!is_f32(x)) return nullptr;
    RCRE_Tensor* out = rcre_tensor_alloc(tape->arena, x->shape, x->ndim);
    if (!out) return nullptr;
    const float* xd = rcre_tensor_f32_data(x);
    float* od = rcre_tensor_f32_data(out);
    for (size_t i = 0; i < out->numel; ++i) {
        od[i] = 1.0f / (1.0f + expf(-xd[i]));
    }

    RCRE_TensorNode* node = tape_push_node(tape);
    if (!node) return out;
    node->out = out;
    node->inputs[0] = x;
    node->num_inputs = 1;
    node->backward = backward_sigmoid;
    return out;
}

/* --- Source: loss.c --- */
/**
 * @file loss.c
 * @brief Numerical and autograd loss functions: MSE, BCE, Cross-Entropy, and KL Divergence.
 *
 * Part of RCRE Unified Engine.
 *
 * Gradient contract (v0.2.2): analytic gradients are written to
 * `grad_out->grad` ONLY. The legacy dual write into `grad_out->data` has
 * been retired: `.data` is the forward-pass buffer and must never be
 * clobbered by a loss function. When `grad_out->grad == NULL` (borrowed
 * core view), only the scalar loss value is computed.
 */

#include <math.h>
#include <string.h>
#include <stdio.h>

static bool loss_is_f32(const RCRE_Tensor* t) {
    return t != nullptr && t->data != nullptr && t->dtype == RCRE_DTYPE_F32;
}

float rcre_loss_mse(const RCRE_Tensor* preds, const RCRE_Tensor* targets, RCRE_Tensor* grad_out) {
    if (!loss_is_f32(preds) || !loss_is_f32(targets) ||
        preds->numel != targets->numel || preds->numel == 0) return 0.0f;

    const float* pd = rcre_tensor_f32_data(preds);
    const float* td = rcre_tensor_f32_data(targets);
    float* g = (grad_out != nullptr) ? grad_out->grad : nullptr;

    size_t n = preds->numel;
    float sum_sq = 0.0f;
    float scale = 2.0f / (float)n;

    for (size_t i = 0; i < n; ++i) {
        float diff = pd[i] - td[i];
        sum_sq += diff * diff;
        if (g != nullptr) g[i] = diff * scale;
    }
    return sum_sq / (float)n;
}

float rcre_loss_bce(const RCRE_Tensor* preds, const RCRE_Tensor* targets, RCRE_Tensor* grad_out) {
    if (!loss_is_f32(preds) || !loss_is_f32(targets) ||
        preds->numel != targets->numel || preds->numel == 0) return 0.0f;

    const float* pd = rcre_tensor_f32_data(preds);
    const float* td = rcre_tensor_f32_data(targets);
    float* g = (grad_out != nullptr) ? grad_out->grad : nullptr;

    size_t n = preds->numel;
    float total_loss = 0.0f;
    const float eps = 1e-12f;

    for (size_t i = 0; i < n; ++i) {
        float p = pd[i];
        if (p < eps) p = eps;
        if (p > 1.0f - eps) p = 1.0f - eps;
        float y = td[i];

        total_loss -= (y * logf(p) + (1.0f - y) * logf(1.0f - p));
        if (g != nullptr) g[i] = ((p - y) / (p * (1.0f - p))) / (float)n;
    }
    return total_loss / (float)n;
}

float rcre_loss_cross_entropy_logits(const RCRE_Tensor* logits, const size_t* targets, size_t batch_size, size_t num_classes, RCRE_Tensor* grad_out) {
    if (!loss_is_f32(logits) || !targets || batch_size == 0 || num_classes == 0) return 0.0f;

    const float* ld = rcre_tensor_f32_data(logits);
    float* g = (grad_out != nullptr) ? grad_out->grad : nullptr;

    float total_loss = 0.0f;
#if defined(RCRE_DEBUG)
    int warned_oob = 0;
#endif

    for (size_t b = 0; b < batch_size; ++b) {
        const float* row = ld + b * num_classes;
        float max_val = row[0];
        for (size_t c = 1; c < num_classes; ++c) {
            if (row[c] > max_val) max_val = row[c];
        }

        float sum_exp = 0.0f;
        for (size_t c = 0; c < num_classes; ++c) {
            sum_exp += expf(row[c] - max_val);
        }

        /* Out-of-range labels: clamp (keeps training alive) and report once
         * per call under RCRE_DEBUG. Validate with rcre_data_validate_labels(). */
        size_t target_cls = targets[b];
        if (target_cls >= num_classes) {
            target_cls = num_classes - 1;
#if defined(RCRE_DEBUG)
            if (!warned_oob) {
                fprintf(stderr,
                        "[rcre] WARNING: rcre_loss_cross_entropy_logits: target[%zu]=%zu is out of "
                        "range [0,%zu); clamping. Validate labels before training.\n",
                        b, targets[b], num_classes);
                warned_oob = 1;
            }
#endif
        }

        float log_p = (row[target_cls] - max_val) - logf(sum_exp + 1e-12f);
        total_loss -= log_p;

        if (g != nullptr) {
            for (size_t c = 0; c < num_classes; ++c) {
                float prob = expf(row[c] - max_val) / (sum_exp + 1e-12f);
                g[b * num_classes + c] = (c == target_cls) ? (prob - 1.0f) / (float)batch_size : prob / (float)batch_size;
            }
        }
    }

    return total_loss / (float)batch_size;
}

float rcre_loss_kl_divergence(const RCRE_Tensor* mu, const RCRE_Tensor* logvar, RCRE_Tensor* grad_mu, RCRE_Tensor* grad_logvar) {
    if (!loss_is_f32(mu) || !loss_is_f32(logvar) ||
        mu->numel != logvar->numel || mu->numel == 0) return 0.0f;

    const float* md = rcre_tensor_f32_data(mu);
    const float* ldv = rcre_tensor_f32_data(logvar);
    float* gm = (grad_mu != nullptr) ? grad_mu->grad : nullptr;
    float* glv = (grad_logvar != nullptr) ? grad_logvar->grad : nullptr;

    size_t n = mu->numel;
    float kl_sum = 0.0f;

    for (size_t i = 0; i < n; ++i) {
        float m = md[i];
        float lv = ldv[i];
        float var = expf(lv);

        /* KL = -0.5 * sum(1 + log(var) - mu^2 - var) */
        kl_sum += -0.5f * (1.0f + lv - m * m - var);

        if (gm != nullptr) gm[i] = m / (float)n;
        if (glv != nullptr) glv[i] = 0.5f * (var - 1.0f) / (float)n;
    }
    return kl_sum / (float)n;
}

int rcre_data_validate_labels(const size_t* targets, size_t n, size_t num_classes) {
    if (!targets) return -1;
    for (size_t i = 0; i < n; ++i) {
        if (targets[i] >= num_classes) return (int)i;
    }
    return -1;
}

/* Scalar Autograd Losses */
RCRE_ScalarVal* rcre_scalar_loss_mse(RCRE_GraphCtx* ctx, RCRE_ScalarVal** preds, const double* targets, size_t count) {
    if (!preds || !targets || count == 0) return nullptr;
    RCRE_ScalarVal* total_loss = rcre_scalar_val_const(ctx, 0.0);
    RCRE_ScalarVal* two = rcre_scalar_val_const(ctx, 2.0);

    for (size_t i = 0; i < count; ++i) {
        RCRE_ScalarVal* t = rcre_scalar_val_const(ctx, targets[i]);
        RCRE_ScalarVal* diff = rcre_scalar_sub(ctx, preds[i], t);
        RCRE_ScalarVal* sq = rcre_scalar_pow(ctx, diff, two);
        total_loss = rcre_scalar_add(ctx, total_loss, sq);
    }
    RCRE_ScalarVal* n_val = rcre_scalar_val_const(ctx, (double)count);
    return rcre_scalar_div(ctx, total_loss, n_val);
}

RCRE_ScalarVal* rcre_scalar_loss_bce(RCRE_GraphCtx* ctx, RCRE_ScalarVal** preds, const double* targets, size_t count) {
    if (!preds || !targets || count == 0) return nullptr;
    RCRE_ScalarVal* total_loss = rcre_scalar_val_const(ctx, 0.0);
    RCRE_ScalarVal* one = rcre_scalar_val_const(ctx, 1.0);

    for (size_t i = 0; i < count; ++i) {
        RCRE_ScalarVal* p = preds[i];
        RCRE_ScalarVal* y = rcre_scalar_val_const(ctx, targets[i]);
        RCRE_ScalarVal* one_minus_y = rcre_scalar_val_const(ctx, 1.0 - targets[i]);

        RCRE_ScalarVal* log_p = rcre_scalar_log(ctx, p);
        RCRE_ScalarVal* one_minus_p = rcre_scalar_sub(ctx, one, p);
        RCRE_ScalarVal* log_one_minus_p = rcre_scalar_log(ctx, one_minus_p);

        RCRE_ScalarVal* term1 = rcre_scalar_mul(ctx, y, log_p);
        RCRE_ScalarVal* term2 = rcre_scalar_mul(ctx, one_minus_y, log_one_minus_p);
        RCRE_ScalarVal* sample_loss = rcre_scalar_neg(ctx, rcre_scalar_add(ctx, term1, term2));

        total_loss = rcre_scalar_add(ctx, total_loss, sample_loss);
    }
    RCRE_ScalarVal* n_val = rcre_scalar_val_const(ctx, (double)count);
    return rcre_scalar_div(ctx, total_loss, n_val);
}

/* --- Source: optim.c --- */
/**
 * @file optim.c
 * @brief High-performance numerical and autograd optimizers: SGD w/ Momentum & AdamW.
 * 
 * Part of RCRE Unified Engine.
 */

#include <stdlib.h>
#include <math.h>
#include <string.h>

static bool optim_is_f32(const RCRE_Tensor* t) {
    return t != nullptr && t->data != nullptr && t->dtype == RCRE_DTYPE_F32;
}

RCRE_TensorOptim* rcre_tensor_optim_sgd_create(RCRE_Arena* arena, RCRE_Tensor** params, size_t num_params, float lr, float momentum, float weight_decay) {
    if (arena == nullptr || params == nullptr || num_params == 0) return nullptr;
    if (!(lr > 0.0f) || !(momentum >= 0.0f && momentum < 1.0f) || !(weight_decay >= 0.0f)) return nullptr;
    for (size_t i = 0; i < num_params; ++i) {
        if (!optim_is_f32(params[i])) return nullptr;
    }

    RCRE_TensorOptim* opt = (RCRE_TensorOptim*)rcre_arena_alloc(arena, sizeof(RCRE_TensorOptim), alignof(RCRE_TensorOptim));
    if (!opt) return nullptr;

    opt->type = RCRE_OPTIM_SGD;
    opt->params = params;
    opt->num_params = num_params;
    opt->lr = lr;
    opt->weight_decay = weight_decay;
    opt->momentum = momentum;

    opt->v_momentum = (float**)rcre_arena_alloc(arena, num_params * sizeof(float*), alignof(float*));
    if (!opt->v_momentum) return nullptr;

    for (size_t p = 0; p < num_params; ++p) {
        size_t bytes = params[p]->numel * sizeof(float);
        opt->v_momentum[p] = (float*)rcre_arena_alloc(arena, bytes, 64);
        if (!opt->v_momentum[p]) return nullptr;
        memset(opt->v_momentum[p], 0, bytes);
    }
    return opt;
}

RCRE_TensorOptim* rcre_tensor_optim_adamw_create(RCRE_Arena* arena, RCRE_Tensor** params, size_t num_params, float lr, float beta1, float beta2, float eps, float weight_decay) {
    if (arena == nullptr || params == nullptr || num_params == 0) return nullptr;
    /* beta == 1.0 makes the bias correction 1 - beta^t == 0 -> divide by zero.
     * Reject it up front instead of emitting NaN/Inf after the first step. */
    if (!(lr > 0.0f) || !(beta1 >= 0.0f && beta1 < 1.0f) || !(beta2 >= 0.0f && beta2 < 1.0f)
        || !(eps > 0.0f) || !(weight_decay >= 0.0f)) return nullptr;
    for (size_t i = 0; i < num_params; ++i) {
        if (!optim_is_f32(params[i])) return nullptr;
    }

    RCRE_TensorOptim* opt = (RCRE_TensorOptim*)rcre_arena_alloc(arena, sizeof(RCRE_TensorOptim), alignof(RCRE_TensorOptim));
    if (!opt) return nullptr;

    opt->type = RCRE_OPTIM_ADAMW;
    opt->params = params;
    opt->num_params = num_params;
    opt->lr = lr;
    opt->beta1 = beta1;
    opt->beta2 = beta2;
    opt->eps = eps;
    opt->weight_decay = weight_decay;
    opt->step_count = 0;

    opt->m = (float**)rcre_arena_alloc(arena, num_params * sizeof(float*), alignof(float*));
    opt->v = (float**)rcre_arena_alloc(arena, num_params * sizeof(float*), alignof(float*));
    if (!opt->m || !opt->v) return nullptr;

    for (size_t p = 0; p < num_params; ++p) {
        size_t bytes = params[p]->numel * sizeof(float);
        opt->m[p] = (float*)rcre_arena_alloc(arena, bytes, 64);
        opt->v[p] = (float*)rcre_arena_alloc(arena, bytes, 64);
        if (!opt->m[p] || !opt->v[p]) return nullptr;
        memset(opt->m[p], 0, bytes);
        memset(opt->v[p], 0, bytes);
    }
    return opt;
}

void rcre_tensor_optim_step(RCRE_TensorOptim* opt) {
    if (opt == nullptr) return;

    if (opt->type == RCRE_OPTIM_SGD) {
        for (size_t p = 0; p < opt->num_params; ++p) {
            RCRE_Tensor* t = opt->params[p];
            if (t->grad == nullptr) continue; /* borrowed param without grad buffer */
            float* td = rcre_tensor_f32_data(t);
            float* v_mom = opt->v_momentum[p];
            for (size_t i = 0; i < t->numel; ++i) {
                float g = t->grad[i] + opt->weight_decay * td[i];
                v_mom[i] = opt->momentum * v_mom[i] + g;
                td[i] -= opt->lr * v_mom[i];
            }
        }
    } else if (opt->type == RCRE_OPTIM_ADAMW) {
        opt->step_count++;
        float b1 = opt->beta1;
        float b2 = opt->beta2;
        float lr = opt->lr;
        float wd = opt->weight_decay;
        float eps = opt->eps;

        float bias_corr1 = 1.0f - powf(b1, (float)opt->step_count);
        float bias_corr2 = 1.0f - powf(b2, (float)opt->step_count);

        for (size_t p = 0; p < opt->num_params; ++p) {
            RCRE_Tensor* t = opt->params[p];
            if (t->grad == nullptr) continue; /* borrowed param without grad buffer */
            float* td = rcre_tensor_f32_data(t);
            float* m_arr = opt->m[p];
            float* v_arr = opt->v[p];

            for (size_t i = 0; i < t->numel; ++i) {
                float g = t->grad[i];
                /* Decoupled weight decay */
                td[i] -= lr * wd * td[i];

                m_arr[i] = b1 * m_arr[i] + (1.0f - b1) * g;
                v_arr[i] = b2 * v_arr[i] + (1.0f - b2) * (g * g);

                float m_hat = m_arr[i] / bias_corr1;
                float v_hat = v_arr[i] / bias_corr2;

                td[i] -= lr * m_hat / (sqrtf(v_hat) + eps);
            }
        }
    }
}

void rcre_tensor_optim_zero_grad(RCRE_TensorOptim* opt) {
    if (opt == nullptr) return;
    for (size_t p = 0; p < opt->num_params; ++p) {
        rcre_tensor_zero_grad(opt->params[p]);
    }
}

/* Scalar Autograd Optimizer */
RCRE_ScalarOptim* rcre_scalar_optim_adamw_create(RCRE_Arena* arena, RCRE_ScalarVal** params, size_t num_params, double lr, double beta1, double beta2, double eps, double weight_decay) {
    if (arena == nullptr || params == nullptr || num_params == 0) return nullptr;
    if (!(lr > 0.0) || !(beta1 >= 0.0 && beta1 < 1.0) || !(beta2 >= 0.0 && beta2 < 1.0)
        || !(eps > 0.0) || !(weight_decay >= 0.0)) return nullptr;
    for (size_t i = 0; i < num_params; ++i) {
        if (!params[i]) return nullptr;
    }

    RCRE_ScalarOptim* opt = (RCRE_ScalarOptim*)rcre_arena_alloc(arena, sizeof(RCRE_ScalarOptim), alignof(RCRE_ScalarOptim));
    if (!opt) return nullptr;

    opt->type = RCRE_OPTIM_ADAMW;
    opt->params = params;
    opt->num_params = num_params;
    opt->lr = lr;
    opt->beta1 = beta1;
    opt->beta2 = beta2;
    opt->eps = eps;
    opt->weight_decay = weight_decay;
    opt->step_count = 0;

    opt->m = (double*)rcre_arena_alloc(arena, num_params * sizeof(double), 64);
    opt->v = (double*)rcre_arena_alloc(arena, num_params * sizeof(double), 64);
    if (!opt->m || !opt->v) return nullptr;

    memset(opt->m, 0, num_params * sizeof(double));
    memset(opt->v, 0, num_params * sizeof(double));
    return opt;
}

void rcre_scalar_optim_step(RCRE_ScalarOptim* opt) {
    if (opt == nullptr) return;
    opt->step_count++;

    double b1 = opt->beta1;
    double b2 = opt->beta2;
    double lr = opt->lr;
    double wd = opt->weight_decay;
    double eps = opt->eps;

    double bias_corr1 = 1.0 - pow(b1, (double)opt->step_count);
    double bias_corr2 = 1.0 - pow(b2, (double)opt->step_count);

    for (size_t i = 0; i < opt->num_params; ++i) {
        RCRE_ScalarVal* p = opt->params[i];
        double g = p->grad;

        /* Decoupled weight decay */
        p->data -= lr * wd * p->data;

        opt->m[i] = b1 * opt->m[i] + (1.0 - b1) * g;
        opt->v[i] = b2 * opt->v[i] + (1.0 - b2) * (g * g);

        double m_hat = opt->m[i] / bias_corr1;
        double v_hat = opt->v[i] / bias_corr2;

        p->data -= lr * m_hat / (sqrt(v_hat) + eps);
    }
}

void rcre_scalar_optim_zero_grad(RCRE_ScalarOptim* opt) {
    if (opt == nullptr) return;
    for (size_t i = 0; i < opt->num_params; ++i) {
        opt->params[i]->grad = 0.0;
    }
}

